volatile int count;
volatile unsigned long uval;
volatile long sval;

static void t_shl (void)
{
    for (int i = 0; i < 5; i++)
        for (int n = 0; n < 32; n++)
        {
            uval = v[i]; count = n;
            test_execute ("shl", (uval << count) == shl_exp[i][n]);
        }
}

static void t_lshr (void)
{
    for (int i = 0; i < 5; i++)
        for (int n = 0; n < 32; n++)
        {
            uval = v[i]; count = n;
            test_execute ("lshr", (uval >> count) == lshr_exp[i][n]);
        }
}

static void t_ashr (void)
{
    for (int i = 0; i < 5; i++)
        for (int n = 0; n < 32; n++)
        {
            sval = (long) v[i]; count = n;
            test_execute ("ashr", (unsigned long) (sval >> count) == ashr_exp[i][n]);
        }
}

TESTFUNC tests[] = { t_shl, t_lshr, t_ashr };
#define TEST_COUNT (sizeof (tests) / sizeof (TESTFUNC))
int main (void) { test_run (tests, TEST_COUNT); return 0; }
